"""Line-table assembly for generated bytecode."""

import dis
import sys

from .opcodes import _python_version


def _encode_varint(value: int) -> bytes:
    result = bytearray()
    while value >= 64:
        result.append((value & 0x3f) | 0x40)
        value >>= 6
    result.append(value)
    return bytes(result)


def _encode_signed_varint(value: int) -> bytes:
    if value < 0:
        value = ((-value) << 1) | 1
    else:
        value <<= 1
    return _encode_varint(value)


def assemble_linetable(source_code, source_instructions, assembled_instructions, default_lineno):
    """Build a line table matching assembled offsets and original source lines."""
    if hasattr(source_code, "co_lines"):
        source_lines = {
            offset: line
            for start, end, line in source_code.co_lines()
            for offset in range(start, end, 2)
        }
    else:
        source_lines = {}
        lineno = source_code.co_firstlineno
        for instruction in dis.get_instructions(source_code):
            if instruction.starts_line is not None:
                lineno = instruction.starts_line
            source_lines[instruction.offset] = lineno

    output = []
    for source, assembled in zip(source_instructions, assembled_instructions):
        original = source.metadata.source
        lineno = source_lines.get(original.offset) if original is not None else None
        if lineno is None or lineno <= 0:
            # Morph instructions (including the injected TOS call) have no
            # original offset, but still need a real line for pdb/tracebacks.
            lineno = default_lineno
        output.append((assembled.offset, assembled.instruction.size_full, lineno))

    if _python_version >= 0x030B:
        # CPython 3.11+ stores source locations in entries spanning up to 8 code
        # units. A no-column entry (kind 13) carries a signed line delta.
        result = bytearray()
        previous_line = source_code.co_firstlineno
        for _, size, lineno in output:
            remaining = size // 2
            while remaining:
                length = min(remaining, 8)
                result.append(0x80 | (13 << 3) | (length - 1))
                result.extend(_encode_signed_varint(lineno - previous_line))
                previous_line = lineno
                remaining -= length
        return bytes(result)

    else:
        # Python 3.9-3.10 use the legacy (byte offset, signed line delta) pairs.
        result = bytearray()
        last_offset = 0
        last_line = source_code.co_firstlineno
        for offset, _, lineno in output:
            if lineno == last_line:
                continue
            byte_delta = offset - last_offset
            line_delta = lineno - last_line
            while byte_delta > 255:
                result.extend((255, 0))
                byte_delta -= 255
            while line_delta > 127:
                result.extend((byte_delta, 127))
                byte_delta = 0
                line_delta -= 127
            while line_delta < -128:
                result.extend((byte_delta, 128))
                byte_delta = 0
                line_delta += 128
            result.extend((byte_delta, line_delta & 0xff))
            last_offset = offset
            last_line = lineno
        return bytes(result)
